sql:
SELECT ROUND(1.0*SUM(CASE WHEN position IN ('President','Vice President','Secretary','Treasurer') THEN c END)/SUM(position IN ('President','Vice President','Secretary','Treasurer')),2) AS avg_officer_events,
ROUND(1.0*SUM(CASE WHEN position NOT IN ('President','Vice President','Secretary','Treasurer') THEN c END)/SUM(position NOT IN ('President','Vice President','Secretary','Treasurer')),2) AS avg_other_events
FROM (SELECT m.position, (SELECT COUNT(*) FROM attendance a WHERE a.link_to_member=m.member_id) AS c FROM member m);

WITH p AS (SELECT ID FROM Patient WHERE Admission='-' AND ID IN (SELECT ID FROM Laboratory WHERE SSA IS NOT NULL AND SSA NOT IN ('','0','negative','-','+-'))),
r AS (SELECT l.ID, MAX(CAST(l.RNP AS REAL)) AS t FROM Laboratory l JOIN p ON p.ID=l.ID WHERE l.RNP IS NOT NULL GROUP BY l.ID)
SELECT ID, t AS RNP FROM r WHERE t=(SELECT MAX(t) FROM r);

SELECT SUM(P.SEX='M') * 1.0 / SUM(P.SEX='F') AS male_to_female_ratio
FROM Patient P
WHERE P.ID IN (
  SELECT L.ID FROM Laboratory L JOIN Patient p2 ON p2.ID = L.ID
  WHERE (p2.SEX='M' AND L.UA > 8.0) OR (p2.SEX='F' AND L.UA > 6.5)
);

SELECT ROUND(1.0*SUM(CASE WHEN position IN ('President','Vice President','Secretary','Treasurer') THEN c END)/SUM(position IN ('President','Vice President','Secretary','Treasurer')),2) AS avg_events_per_officer,
ROUND(1.0*SUM(CASE WHEN position NOT IN ('President','Vice President','Secretary','Treasurer') THEN c END)/SUM(position NOT IN ('President','Vice President','Secretary','Treasurer')),2) AS avg_events_per_other_student
FROM (SELECT m.position, (SELECT COUNT(*) FROM attendance a WHERE a.link_to_member=m.member_id) AS c FROM member m);

SELECT ROUND(1.0 * (SELECT COUNT(*) FROM pitStops p WHERE p.raceId IN (SELECT raceId FROM races WHERE year = 2017 AND name NOT IN (SELECT name FROM races WHERE year = 2000))) / COUNT(*), 2) AS avg_pit_stops_per_race
FROM races
WHERE year = 2017 AND name NOT IN (SELECT name FROM races WHERE year = 2000);

WITH a AS (SELECT atom_id, element FROM atom JOIN molecule USING(molecule_id) WHERE label='+'),
b AS (SELECT element, COUNT(*) c FROM a WHERE atom_id IN (SELECT atom_id FROM connected UNION SELECT atom_id2 FROM connected) GROUP BY element)
SELECT element, ROUND(100.0*(SELECT COUNT(*) FROM a WHERE a.element=b.element)/(SELECT COUNT(*) FROM a),2) AS pct FROM b WHERE c=(SELECT MAX(c) FROM b);

WITH last AS (
  SELECT cs.constructorId, r.year, cs.points,
         ROW_NUMBER() OVER (PARTITION BY cs.constructorId, r.year ORDER BY r.round DESC, r.date DESC) rn
  FROM constructorStandings cs JOIN races r ON r.raceId = cs.raceId
), tot AS (
  SELECT c.constructorId, c.name, c.url, COALESCE(SUM(l.points),0) pts
  FROM constructors c LEFT JOIN last l ON l.constructorId=c.constructorId AND l.rn=1
  WHERE c.nationality='Italian' GROUP BY c.constructorId
), ranked AS (
  SELECT name, pts, url, RANK() OVER (ORDER BY pts DESC) rk FROM tot
)
SELECT name, pts AS career_points, url FROM ranked WHERE rk<=3 ORDER BY rk, name;

WITH w AS (SELECT COUNT(*) c FROM attendance WHERE link_to_event=(SELECT event_id FROM event WHERE event_name='Women''s Soccer')),
a AS (SELECT ROUND(AVG(n),1) av FROM (SELECT (SELECT COUNT(*) FROM attendance t WHERE t.link_to_event=e.event_id) n FROM event e WHERE substr(event_date,1,10) BETWEEN '2019-09-01' AND '2019-11-30'))
SELECT w.c AS womens_soccer_attendance, a.av AS avg_fall_2019_attendance, CASE WHEN w.c>a.av THEN 'more' WHEN w.c<a.av THEN 'fewer' ELSE 'equal' END AS verdict FROM w, a;

WITH d AS (SELECT district_id FROM district ORDER BY A11 LIMIT 1),
c AS (SELECT client_id FROM client WHERE gender='F' AND district_id=(SELECT district_id FROM d) ORDER BY birth_date ASC LIMIT 1)
SELECT disp.account_id, (SELECT MAX(A11)-MIN(A11) FROM district) AS diff FROM disp WHERE client_id=(SELECT client_id FROM c);

WITH s AS (
 SELECT DISTINCT l.ID FROM Laboratory l JOIN Patient p ON p.ID=l.ID
 WHERE p.Admission='-' AND l.SSA IS NOT NULL AND l.SSA NOT IN ('negative','0','-','+-')
),
r AS (
 SELECT l.ID, CAST(l.RNP AS REAL) AS t FROM Laboratory l JOIN s ON s.ID=l.ID
 WHERE l.RNP GLOB '[0-9]*'
)
SELECT ID, t AS RNP FROM r WHERE t=(SELECT MAX(t) FROM r) GROUP BY ID, t;

WITH cur AS (
  SELECT player_api_id, overall_rating, defensive_work_rate,
    ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) rn
  FROM Player_Attributes WHERE date < '2013-07-13'
), c AS (
  SELECT * FROM cur WHERE rn=1 AND defensive_work_rate IN ('low','medium','high') AND overall_rating IS NOT NULL
)
SELECT ROUND((SELECT overall_rating FROM c JOIN Player p USING(player_api_id) WHERE p.player_name='Landon Donovan') * 100.0 / AVG(overall_rating) - 100, 2) AS pct FROM c;

WITH t AS (SELECT DISTINCT c.type, d.district_id, d.A2 name, CAST(d.A4 AS INTEGER) pop
FROM card c JOIN disp p ON c.disp_id=p.disp_id JOIN client cl ON cl.client_id=p.client_id JOIN district d ON d.district_id=cl.district_id)
SELECT type, name, pop FROM t WHERE pop=(SELECT MIN(pop) FROM t t2 WHERE t2.type=t.type) ORDER BY type, name;

WITH c AS (
 SELECT player_api_id, overall_rating, defensive_work_rate,
  ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) rn
 FROM Player_Attributes WHERE date < '2013-07-13'
), r AS (SELECT * FROM c WHERE rn=1 AND defensive_work_rate IN ('low','medium','high') AND overall_rating IS NOT NULL)
SELECT ROUND((SELECT overall_rating FROM r WHERE player_api_id=30700)*100.0/(SELECT AVG(overall_rating) FROM r)-100,2) AS pct;

WITH last AS (
  SELECT cs.constructorId, r.year, cs.points,
         ROW_NUMBER() OVER (PARTITION BY cs.constructorId, r.year ORDER BY r.round DESC) rn
  FROM constructorStandings cs JOIN races r ON r.raceId = cs.raceId
), tot AS (
  SELECT c.name, c.url, COALESCE(SUM(l.points),0) pts
  FROM constructors c LEFT JOIN last l ON l.constructorId=c.constructorId AND l.rn=1
  WHERE c.nationality='Italian' GROUP BY c.constructorId
), ranked AS (SELECT *, RANK() OVER (ORDER BY pts DESC) rk FROM tot)
SELECT name, pts AS career_points, url FROM ranked WHERE rk<=3 ORDER BY pts DESC, name;

with f as (select * from cards where borderColor='black' and (','||replace(availability,' ','')||',') like '%,arena,%' and power glob '[0-9]*' and cast(power as int)>=10 and artist is not null),
c as (select artist, count(*) n from f group by artist)
select artist, n from c where n=(select max(n) from c);

WITH m AS (SELECT season, away_player_1 p1,away_player_2 p2,away_player_3 p3,away_player_4 p4,away_player_5 p5,away_player_6 p6,away_player_7 p7,away_player_8 p8,away_player_9 p9,away_player_10 p10,away_player_11 p11 FROM Match WHERE home_team_goal-away_team_goal>=5),
u AS (SELECT season,p1 p FROM m UNION SELECT season,p2 FROM m UNION SELECT season,p3 FROM m UNION SELECT season,p4 FROM m UNION SELECT season,p5 FROM m UNION SELECT season,p6 FROM m UNION SELECT season,p7 FROM m UNION SELECT season,p8 FROM m UNION SELECT season,p9 FROM m UNION SELECT season,p10 FROM m UNION SELECT season,p11 FROM m)
SELECT season, COUNT(p) AS player_count FROM u WHERE p IS NOT NULL GROUP BY season ORDER BY season;

WITH last AS (
  SELECT player_api_id, MAX(date) AS d FROM Player_Attributes
  WHERE date <= '2013-07-12 23:59:59' GROUP BY player_api_id
), cur AS (
  SELECT pa.player_api_id, pa.overall_rating
  FROM Player_Attributes pa JOIN last l ON l.player_api_id=pa.player_api_id AND l.d=pa.date
  WHERE pa.overall_rating IS NOT NULL AND pa.defensive_work_rate IN ('low','medium','high')
)
SELECT ROUND((SELECT overall_rating FROM cur WHERE player_api_id=(SELECT player_api_id FROM Player WHERE player_name='Landon Donovan')) * 100.0
  / (SELECT AVG(overall_rating) FROM cur) - 100, 2) AS pct;

with l as (select ID, RNP, row_number() over (partition by ID order by Date desc) r from Laboratory)
select sum(p.SEX='F') - sum(p.SEX='M') as diff
from l join Patient p using(ID)
where r=1 and RNP glob '[0-9]*' and cast(RNP as real) >= 32;

WITH j AS (SELECT p.Admission AS a, p.ID AS id, l."T-CHO" AS t FROM Laboratory l JOIN Patient p ON p.ID=l.ID WHERE p.Admission IN ('+','-') AND l."T-CHO" IS NOT NULL),
m AS (SELECT a, MAX(t) AS mx FROM j GROUP BY a)
SELECT DISTINCT j.t AS "T-CHO", j.a AS Admission, j.id AS ID FROM j JOIN m ON j.a=m.a AND j.t=m.mx ORDER BY (j.a='-'), j.id;

WITH rare AS (
  SELECT element FROM atom GROUP BY element HAVING COUNT(DISTINCT molecule_id)=1
), ra AS (
  SELECT a.atom_id, a.molecule_id FROM atom a JOIN rare USING(element)
  JOIN molecule m ON m.molecule_id=a.molecule_id WHERE m.label='+'
)
SELECT ra.molecule_id, COUNT(DISTINCT c.bond_id) AS bond_count
FROM ra JOIN connected c ON c.atom_id=ra.atom_id OR c.atom_id2=ra.atom_id
GROUP BY ra.molecule_id ORDER BY ra.molecule_id;

WITH m(k) AS (VALUES('01'),('02'),('03'),('04'),('05'),('06'),('07'),('08'),('09'),('10'),('11'),('12')),
c AS (SELECT substr(l.CreationDate,6,2) k, COUNT(DISTINCT l.RelatedPostId) n FROM postLinks l JOIN posts p ON p.Id=l.RelatedPostId WHERE l.CreationDate LIKE '2010-%' AND p.AnswerCount<=2 GROUP BY k)
SELECT ROUND(AVG(COALESCE(c.n,0)),2) FROM m LEFT JOIN c USING(k);

WITH RECURSIVE s(id, item, rest) AS (
  SELECT e.expense_id, '', e.expense_description || ',' FROM expense e JOIN budget b ON b.budget_id = e.link_to_budget WHERE b.category = 'Food'
  UNION ALL
  SELECT id, lower(trim(substr(rest, 1, instr(rest, ',') - 1))), substr(rest, instr(rest, ',') + 1) FROM s WHERE rest <> ''
)
SELECT item AS item_name, COUNT(DISTINCT id) AS record_count FROM s WHERE item <> '' GROUP BY item ORDER BY record_count DESC, item LIMIT 1;

WITH e AS (SELECT ID FROM Patient WHERE Admission='-' AND ID IN (SELECT ID FROM Laboratory WHERE HGB<10)),
m AS (SELECT l.ID, MAX(CAST(l.RNP AS INTEGER)) r FROM Laboratory l JOIN e USING(ID) WHERE l.RNP GLOB '[0-9]*' GROUP BY l.ID)
SELECT m.ID, p.SEX, m.r AS RNP FROM m JOIN Patient p ON p.ID=m.ID WHERE m.r=(SELECT MAX(r) FROM m);

WITH latest AS (
  SELECT player_api_id, MAX(date) d FROM Player_Attributes WHERE date <= '2010-12-31 23:59:59' GROUP BY player_api_id
), sel AS (
  SELECT pa.player_api_id FROM Player_Attributes pa JOIN latest l ON pa.player_api_id=l.player_api_id AND pa.date=l.d WHERE pa.overall_rating > 80
), appear AS (
  SELECT m.match_api_id, p.pid FROM "Match" m
  JOIN (SELECT match_api_id mid, home_player_1 pid FROM "Match" UNION ALL SELECT match_api_id, home_player_2 FROM "Match" UNION ALL SELECT match_api_id, home_player_3 FROM "Match" UNION ALL SELECT match_api_id, home_player_4 FROM "Match" UNION ALL SELECT match_api_id, home_player_5 FROM "Match" UNION ALL SELECT match_api_id, home_player_6 FROM "Match" UNION ALL SELECT match_api_id, home_player_7 FROM "Match" UNION ALL SELECT match_api_id, home_player_8 FROM "Match" UNION ALL SELECT match_api_id, home_player_9 FROM "Match" UNION ALL SELECT match_api_id, home_player_10 FROM "Match" UNION ALL SELECT match_api_id, home_player_11 FROM "Match"
   UNION ALL SELECT match_api_id, away_player_1 FROM "Match" UNION ALL SELECT match_api_id, away_player_2 FROM "Match" UNION ALL SELECT match_api_id, away_player_3 FROM "Match" UNION ALL SELECT match_api_id, away_player_4 FROM "Match" UNION ALL SELECT match_api_id, away_player_5 FROM "Match" UNION ALL SELECT match_api_id, away_player_6 FROM "Match" UNION ALL SELECT match_api_id, away_player_7 FROM "Match" UNION ALL SELECT match_api_id, away_player_8 FROM "Match" UNION ALL SELECT match_api_id, away_player_9 FROM "Match" UNION ALL SELECT match_api_id, away_player_10 FROM "Match" UNION ALL SELECT match_api_id, away_player_11 FROM "Match") p ON p.mid=m.match_api_id
  WHERE m.season='2010/2011'
)
SELECT ROUND(AVG(cnt),2) AS avg_matches FROM (
  SELECT s.player_api_id, COUNT(DISTINCT a.match_api_id) cnt FROM sel s LEFT JOIN appear a ON a.pid=s.player_api_id GROUP BY s.player_api_id
)
